node --input-type=module <<'EOF'
import { permit } from './limit.mjs';
const cases = [
  [-1, false], [0, true], [3, true], [4, false],
  ['0', false], [null, false], [NaN, false], [1.5, false], [undefined, false], [Infinity, false], [-Infinity, false]
];
for (const [input, expected] of cases) {
  const actual = permit(input);
  console.log(`${String(input)} (${typeof input}) => ${actual}; expected ${expected}; ${Object.is(actual, expected) ? 'PASS' : 'FAIL'}`);
}
EOF
